@app.route("/")
def home():
    # Hosted services set PORT and provide a public host. Use the current request host for the QR.
    site_url = request.url_root.rstrip("/")
    im = qrcode.make(site_url)
    b = io.BytesIO()
    im.save(b, format="PNG")
    return render_template_string(HTML, qr=base64.b64encode(b.getvalue()).decode(), site_url=site_url)
@app.route("/health")
def health():
    return {"status":"ok"}
